function coverResults(R){
 const section=(title,subtitle,arr,fn)=>arr.length?`<section class="option-section"><h2>${title}<span>${arr.length}</span></h2>${groupByColleague(arr).map(options=>options.map(fn).join('')).join('')}</section>`:'';
 return swapRecoveryV(R)+(R.rows.length>1?`${R.all.length?`<section class="common-cover"><h2>${T2('Can cover all selected shifts','جایگزین برای همهٔ شیفت‌های انتخاب‌شده')}</h2><p>${R.all.map(m=>colleagueLabel(m)).join('، ')}</p></section>`:''}`:'')+R.rows.map(r=>{const cover=[...r.free,...r.ext],shownCover=true,shownSwap=true;const pending=[...r.unk,...r.pending],unique=[...new Map(pending.map(x=>[x.m.id+'|'+x.reason+'|'+x.date,x])).values()];return`<section class="shift-options"><div class="selected-shift-heading"><b>${codeHTML(r.h.text)} · ${dateHTML(r.h.date)}</b><span>${T2('Your shift','شیفت شما')}</span></div>`+

 (shownSwap?section(T2('You exchange two shifts','تعویض دوطرفه'),T2('They take yours; you take one of theirs.','برنامه پس از تعویض:'),r.swap,x=>exchangeCard(r,x)):'')+
 (shownCover?section(T2('Someone takes your shift','واگذاری شیفت'),T2('No shift to take in return.','شیفتتان را به همکار واگذار می‌کنید.'),cover,x=>coverCard(r,x)):'')+
 (!(shownCover&&cover.length)&&!(shownSwap&&r.swap.length)?`<div class="c empty-options"><b>${T2('No confirmed suggestion yet','هنوز پیشنهاد تأییدشده‌ای نداریم')}</b><p>${T2('Check missing roster dates or colleague preferences.','هنوز گزینهٔ مطمئنی پیدا نکردم؛ بیا برنامهٔ همکارها رو بررسی کنیم.')}</p></div>`:'')+
 (unique.length?`<details class="review-options-note"><summary>${unique.length} ${T2('items need roster review','مورد نیاز به بررسی برنامه')}</summary>${unique.map(x=>`<p><b>${colleagueLabel(x.m)}</b> · ${dateHTML(x.date||r.h.date)}<br>${esc(swapReason(x))}<button class="text-button" onclick="reviewSwapDate(${jsArg(x.self?(x.workplace||r.h.wp):r.h.wp)},${jsArg(x.m.id)},${jsArg(x.date||r.h.date)},${!!x.self})">${T2('Check this date','بررسی این روز')}</button></p>`).join('')}<button class="text-button" onclick="openRoster(${jsArg(r.h.wp)})">${T2('Review roster table','بررسی جدول شیفت‌ها')}</button></details>`:'')+
 ([...r.blocked,...(r.conflicts||[])].length?`<details class="blocked-options"><summary>${T2('Options with limits or conflicts','گزینه‌های دارای محدودیت یا تداخل')}</summary>${[...r.blocked,...(r.conflicts||[])].map(x=>`<p><b>${colleagueLabel(x.m)}</b>${x.date?' · '+dateHTML(x.date):''}<br>${esc(swapReason(x))}</p>`).join('')}</details>`:'')+`</section>`}).join('');
}

const covV=w=>{const R=tc.res?coverCalc(w,tc.dates):null;if(tc.res)tc.res=R;const my=S.shifts.filter(h=>h.wp===w.id&&h.date>=iso(Date.now())&&h.segs.length).sort((a,b)=>a.date.localeCompare(b.date));
 if(!tc.cm)tc.cm=mfirst(new Date((my[0]?.date||iso(Date.now()))+'T00:00'));
 const picker=swapCalendarV(w),selection=swapSelectionV(w),btn=`<button class="p cover-submit" onclick="coverGo()" ${tc.dates.length&&mates(w.id).length?'':'disabled'}>${T2('Find shift options','پیدا کردن پیشنهادها')}${tc.dates.length?` · ${tc.dates.length}`:''}</button>`;
 const multiple=`<label class="multi-shift-choice"><input type="checkbox" ${tc.multiple?'checked':''} onchange="setCoverMultiple(this.checked)">${T2('Select several shifts','انتخاب چند شیفت')}</label>`;
 if(!R)return (tc.notice?`<div class="c saved-exchange" role="status"><b>✓ ${bidi(tc.notice)}</b></div>`:'')+`<h1 class="swap-title">${T2('Which shift would you like to change?','کدوم شیفتت رو می‌خوای عوض کنی؟')}</h1>`+`<p class="friendly-prompt swap-prompt">${T2('Select a shift, then let’s look at the options.','شیفتت رو انتخاب کن، بعد با هم گزینه‌ها رو بررسی می‌کنیم.')}</p>`+picker+multiple+selection+btn+(mates(w.id).length?'':noMates());
 return `<details class="selection-details"><summary>${tc.dates.map(id=>{const h=S.shifts.find(h=>h.id===id);return h?dateHTML(h.date)+' · '+codeHTML(h.text):''}).join('، ')} · ${T2('Change selection','تغییر انتخاب')}</summary>${picker}${multiple}${selection}${btn}</details>`+coverResults(R)};

function calendarDays(first){const key=d=>S.cal==='j'?jp(d).m:d.getMonth(),out=Array((first.getDay()-S.fdow+7)%7).fill(null);for(let d=first;key(d)===key(first);d=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1))out.push(d);return out}
function weekdaysHTML(){return Array.from({length:7},(_,i)=>{const d=new Date(2024,0,7+(i+S.fdow)%7);return `<span class="weekday ${isWeekend(d)?'holiday':''}" title="${d.toLocaleDateString(loc(),{weekday:'long'})}">${weekdayLabel(d)}</span>`}).join('')}
function moveCoverMonth(n){const d=mfirst(tc.cm);tc.cm=mfirst(n>0?new Date(d.getFullYear(),d.getMonth(),d.getDate()+32):new Date(d.getFullYear(),d.getMonth(),d.getDate()-1));tc.res=null;render()}
function toggleCoverDay(date){const w=curWp(),hs=S.shifts.filter(h=>h.wp===w.id&&h.date===date&&h.date>=iso(Date.now())&&h.segs.length);if(!hs.length)return;const all=hs.every(h=>tc.dates.includes(h.id));if(!tc.multiple&&!all)tc.dates=[];for(const h of hs)tc.dates=all?tc.dates.filter(id=>id!==h.id):[...new Set([...tc.dates,h.id])];tc.res=null;render()}
const cmpV=w=>{const ms=mates(w.id),m=ms.find(x=>x.id===tc.mate),sel=`<details class="colleague-picker" ${m?'':'open'}><summary>${m?colleagueLabel(m):T2('Choose a colleague','همکار مورد نظر را انتخاب کنید')}</summary>${colleagueChoices(ms,tc.mate,id=>`tc.mate=${jsArg(id)};render()`)}</details>`;
  if(!m)return sel;const mine={};S.shifts.filter(h=>h.wp===w.id).forEach(h=>mine[h.date]=h.text);
  const both=[],a=[],b=[];for(const d of [...new Set([...Object.keys(mine),...Object.keys(m.cells)])].sort()){if((m.uns||[]).includes(d))continue;const x=mine[d]||'',y=m.cells[d]||'',xw=isWork(w,x),yw=isWork(w,y);if(xw&&yw)both.push([d,x,y]);else if(xw&&isOff(w,y))a.push([d,x]);else if(yw&&isOff(w,x))b.push([d,y])}
  const L=(t,arr,f)=>`<h1>${t} (${arr.length})</h1>`+(arr.length?`<div class="c">${arr.map(f).join('<br>')}</div>`:`<div class="c mu">—</div>`);
  return sel+((m.uns||[]).length?`<p class="c scan-notice">${T2('Dates needing scan review are excluded from this comparison.','چند روز از برنامه نیاز به بررسی دارد.')}</p>`:'')+L(T2('Working together','روزهایی که هر دو شیفت دارید'),both,([d,x,y])=>`${dlabel(d)} · ${codeHTML(x)} / ${codeHTML(y)}`)+L(T2('I work, they are off','روزهای off همکار'),a,([d,x])=>`${dlabel(d)} · ${codeHTML(x)}`)+L(T2('They work, I am off','روزهای off شما'),b,([d,y])=>`${dlabel(d)} · ${codeHTML(y)}`)};
V.team=()=>{if(!S.wps.length)return`<div class="empty"><p class="mu">${T2('Add a workplace first.','ابتدا محل کارتان را وارد کنید.')}</p><button class="p" onclick="go('places')">Add workplace</button></div>`;
  const w=curWp();tc.wp=w.id;const ms=mates(w.id);
  if(tc.busy)return`<div class="c"><div class="pbar"><i></i></div><div id="prog" class="mu" style="margin-top:8px"></div><button class="p s" style="margin-top:10px" onclick="tc.cancel=1">${T2('Cancel','لغو')}</button></div>`;
  const wsel=S.wps.length>1?`<select onchange="tc.wp=this.value;tc.res=null;tc.dates=[];tc.month='';tc.cm=null;tc.mate='';render()">${S.wps.map(x=>`<option value="${esc(x.id)}" ${x.id===w.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'';
  const people=tc.v==='cmp';
  const heading=`<div class="team-heading">${people?`<h1>${T2('Colleague preferences','تنظیمات همکاران')}</h1>`:''}<div class="team-tools">${people?`<button class="text-button" onclick="tc.v='cover';render()">${T2('Back to shift swap','برگشت به تعویض شیفت')}</button>`:`<button class="text-button" onclick="openColleagues()">${T2('Colleague limits','محدودیت‌های همکاران')}</button>`}<button class="text-button" onclick="openRoster(${jsArg(w.id)})">${T2('Roster table','جدول شیفت‌ها')}</button></div></div>`;
  return wsel+(people?heading+(!ms.length?noMates():colleaguesV(w)):heading+covV(w))};

// Reads every other row of the last scanned sheet and stores them as colleagues (device only).
const cleanName=s=>(s||'').replace(/[\u200c\u200e\u200f|\[\]_]/g,' ').replace(/\s+/g,' ').trim();
async function readAll(options={}){
 const w=S.wps.find(x=>x.id===sc.wp);if(!w||!sc.pages||tc.busy)return false;
 const unchecked=sc.pages.findIndex(p=>p.guess);if(unchecked>=0){sc.continueReadAll=true;tab='scan';openDateCheck(unchecked);return false}
 const dates=scanImportDates(),sources=sc.pages.map(p=>p.sourceKey),mode=options.mode||getRosterImportMode('colleagues',w.id,dates,{others:true,sources,payload:JSON.stringify([sc.ri,sc.rows.map(r=>[r.pi,r.index,r.y0,r.y1,r.nm])])});if(!mode)return false;
 const change=options.change||beginChange('Colleague roster','برنامهٔ همکاران',['mates','rosterImports']);change.importKind='photo';const rows=sc.rows.filter((r,i)=>i!==sc.ri),collected=[];tc.busy=true;tc.readingRoster=true;tc.cancel=false;tab='scan';render();let error='';
 try{const wk=await scanWorker('eng'),J=S.cal==='j',b0=J?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1);await wk.setParameters({tessedit_pageseg_mode:'7',tessedit_char_whitelist:codeTokens(w)});
  for(let q=0;q<rows.length;q++){if(tc.cancel)break;const r=rows[q];usePage(r.pi);const V=sc.vl,cells={},uns=[],scan={};P(T2('Reading colleague ','در حال خواندن برنامهٔ همکار ')+(q+1)+'/'+rows.length,q/rows.length);
   for(let i=0;i<V.length-1;i++){if(tc.cancel)break;const day=sc.dayAt(i);if(day<1||day>31||scanNameOverlap(sc,i))continue;const d=new Date(b0.getFullYear(),b0.getMonth(),b0.getDate()+day-1);if(!(J?jp(d).m===sc.m:d.getMonth()===sc.m-1))continue;const result=await recognizeShift(w,wk,...cellBounds(V[i],r.y0,V[i+1],r.y1)),t=result.text;if(sc.guess||result.c<80||result.uncertain||!t||!parse(w,t))uns.push(iso(d));scan[iso(d)]=scanEvidence(result);if(t&&parse(w,t))cells[iso(d)]=t}
   collected.push({r,cells,uns,scan,existing:matchingScannedColleague(w.id,r,rows)?.id})
  }
 }catch(e){error=e.message||'Scan failed'}
 if(error||tc.cancel){if(options.change)restoreImportChange(change);tc.busy=false;tc.readingRoster=false;await killWk();if(options.change){tab='scan';sc.pick=false}else{tab='scan';sc.pick=false;sc.method='photo'}render();showChangeFeedback(tc.cancel?T2('Import cancelled. Saved rosters were kept.','افزودن لغو شد؛ برنامهٔ قبلی حفظ شد.'):T2('Could not finish. Saved rosters were kept; try again.','خواندن کامل نشد؛ برنامهٔ قبلی حفظ شد. دوباره تلاش کن.'));return false}
 if(mode==='replace')clearColleagueImportDates(w.id,dates);
 const used=new Set();for(const [q,item]of collected.entries()){const {r,cells,uns,scan}=item,name=cleanName(r.nm),source=scanRowSource(r);let ex=item.existing&&!used.has(item.existing)?S.mates.find(m=>m.id===item.existing&&m.wp===w.id):null;
  if(!ex){ex={id:'m'+Date.now()+'-'+q+'-'+Math.random().toString(36).slice(2,6),wp:w.id,name:name||'',nameConfirmed:!!r.nameConfirmed,cells:{},uns:[]};S.mates.push(ex)}used.add(ex.id);
  for(const date of Object.keys(scan))delete ex.cells[date];Object.assign(ex.cells,cells);ex.uns=[...(ex.uns||[]).filter(x=>!(x in scan)),...uns];ex.scan={...ex.scan,...scan};ex.scan=Object.fromEntries(Object.entries(ex.scan).sort(([a],[b])=>b.localeCompare(a)).slice(0,62));Object.assign(ex,{img:r.img,rawName:r.rawName||r.nm,nameFeature:r.nameFeature});if(source)ex.scanSources=[...new Set([...(ex.scanSources||[]),source])].slice(-12)
 }
 recordRosterImport('photo',w.id,dates,sources);const saved=await commitChange(change);tc.busy=false;tc.readingRoster=false;await killWk();if(!saved){if(options.change)tab='scan';render();return false}sc.cells=null;sc.pick=false;tc.res=null;roster.review=false;roster.cm=mfirst(S.cal==='j'?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1));roster.page=0;roster.date=dates[0]||'';finishRosterImport('photo',w.id,dates.length?dates:[iso(Date.now())]);return true
}
